import { useState, useRef, useCallback, useEffect } from "react";
import type { AISuggestionMode } from "./useAISuggestion";

export interface AutofillSuggestion {
  value: string;
  confidence: number;
  source: "history" | "ai" | "pattern";
}

export interface UseSmartFormAutofillOptions {
  fieldName: string;
  fieldType?: "text" | "email" | "name" | "address" | "search" | "custom";
  formContext?: Record<string, string>;
  apiEndpoint?: string;
  debounceMs?: number;
  minLength?: number;
  maxSuggestions?: number;
  onSelect?: (value: string) => void;
}

export interface UseSmartFormAutofillReturn {
  suggestions: AutofillSuggestion[];
  isOpen: boolean;
  loading: boolean;
  error: string | null;
  activeIndex: number;
  inputProps: {
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => void;
    onKeyDown: (e: React.KeyboardEvent) => void;
    onFocus: () => void;
    onBlur: () => void;
    "aria-expanded": boolean;
    "aria-autocomplete": "list";
    "aria-controls": string;
    "aria-activedescendant": string | undefined;
    role: "combobox";
  };
  listProps: {
    id: string;
    role: "listbox";
    "aria-label": string;
  };
  getItemProps: (index: number) => {
    id: string;
    role: "option";
    "aria-selected": boolean;
    onClick: () => void;
    onMouseEnter: () => void;
  };
  selectSuggestion: (value: string) => void;
  dismiss: () => void;
  fetchSuggestions: (value: string) => void;
}

// ── In-memory cache ────────────────────────────────────────────────────────
const cache = new Map<string, { data: AutofillSuggestion[]; ts: number }>();
const CACHE_TTL = 60_000; // 1 minute

function getCached(key: string): AutofillSuggestion[] | null {
  const entry = cache.get(key);
  if (!entry) return null;
  if (Date.now() - entry.ts > CACHE_TTL) {
    cache.delete(key);
    return null;
  }
  return entry.data;
}

function setCached(key: string, data: AutofillSuggestion[]) {
  cache.set(key, { data, ts: Date.now() });
  // Keep cache bounded
  if (cache.size > 100) {
    const firstKey = cache.keys().next().value;
    if (firstKey) cache.delete(firstKey);
  }
}

export function useSmartFormAutofill({
  fieldName,
  fieldType = "text",
  formContext = {},
  apiEndpoint = "/api/suggest",
  debounceMs = 350,
  minLength = 2,
  maxSuggestions = 5,
  onSelect,
}: UseSmartFormAutofillOptions): UseSmartFormAutofillReturn {
  const [suggestions, setSuggestions] = useState<AutofillSuggestion[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeIndex, setActiveIndex] = useState(-1);

  const abortRef = useRef<AbortController | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastValueRef = useRef("");

  const listId = `autofill-list-${fieldName.replace(/\s+/g, "-")}`;

  const dismiss = useCallback(() => {
    setIsOpen(false);
    setActiveIndex(-1);
  }, []);

  const selectSuggestion = useCallback(
    (value: string) => {
      onSelect?.(value);
      dismiss();
    },
    [onSelect, dismiss]
  );

  const fetchSuggestions = useCallback(
    (value: string) => {
      if (!value || value.length < minLength) {
        setSuggestions([]);
        setIsOpen(false);
        return;
      }

      if (value === lastValueRef.current) return;
      lastValueRef.current = value;

      if (timerRef.current) clearTimeout(timerRef.current);
      if (abortRef.current) abortRef.current.abort();

      const cacheKey = `autofill:${fieldName}:${fieldType}:${value}`;
      const cached = getCached(cacheKey);
      if (cached) {
        setSuggestions(cached.slice(0, maxSuggestions));
        setIsOpen(cached.length > 0);
        return;
      }

      timerRef.current = setTimeout(async () => {
        const controller = new AbortController();
        abortRef.current = controller;
        setLoading(true);
        setError(null);

        try {
          const customKey =
            typeof window !== "undefined"
              ? localStorage.getItem("gemini_api_key") || ""
              : "";

          const contextText = Object.entries(formContext)
            .filter(([, v]) => v)
            .map(([k, v]) => `${k}: ${v}`)
            .join(", ");

          const mode: AISuggestionMode = "autofill" as AISuggestionMode;

          const res = await fetch(apiEndpoint, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "x-api-key": customKey,
            },
            body: JSON.stringify({
              text: value,
              context: `Field: ${fieldName}, Type: ${fieldType}${contextText ? `, Form data: ${contextText}` : ""}`,
              mode,
            }),
            signal: controller.signal,
          });

          const data = await res.json();
          if (!res.ok) throw new Error(data?.error || "Request failed");

          const raw: AutofillSuggestion[] = (data.suggestions || [])
            .slice(0, maxSuggestions)
            .map((s: string | AutofillSuggestion, i: number) =>
              typeof s === "string"
                ? { value: s, confidence: 1 - i * 0.1, source: "ai" as const }
                : s
            );

          setCached(cacheKey, raw);
          setSuggestions(raw);
          setIsOpen(raw.length > 0);
        } catch (err) {
          if (err instanceof DOMException && err.name === "AbortError") return;
          const msg = err instanceof Error ? err.message : "Connection error";
          setError(msg);
          setIsOpen(false);
        } finally {
          setLoading(false);
        }
      }, debounceMs);
    },
    [fieldName, fieldType, formContext, apiEndpoint, debounceMs, minLength, maxSuggestions]
  );

  // Keyboard navigation
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (!isOpen || suggestions.length === 0) return;

      switch (e.key) {
        case "ArrowDown":
          e.preventDefault();
          setActiveIndex((i) => Math.min(i + 1, suggestions.length - 1));
          break;
        case "ArrowUp":
          e.preventDefault();
          setActiveIndex((i) => Math.max(i - 1, -1));
          break;
        case "Enter":
          e.preventDefault();
          if (activeIndex >= 0) {
            selectSuggestion(suggestions[activeIndex].value);
          }
          break;
        case "Escape":
          dismiss();
          break;
        case "Tab":
          if (activeIndex >= 0) {
            e.preventDefault();
            selectSuggestion(suggestions[activeIndex].value);
          } else {
            dismiss();
          }
          break;
      }
    },
    [isOpen, suggestions, activeIndex, selectSuggestion, dismiss]
  );

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
      if (abortRef.current) abortRef.current.abort();
    };
  }, []);

  return {
    suggestions,
    isOpen,
    loading,
    error,
    activeIndex,
    inputProps: {
      onChange: (e) => fetchSuggestions(e.target.value),
      onKeyDown: handleKeyDown,
      onFocus: () => {
        if (suggestions.length > 0) setIsOpen(true);
      },
      onBlur: () => setTimeout(dismiss, 150),
      "aria-expanded": isOpen,
      "aria-autocomplete": "list",
      "aria-controls": listId,
      "aria-activedescendant":
        activeIndex >= 0 ? `${listId}-item-${activeIndex}` : undefined,
      role: "combobox",
    },
    listProps: {
      id: listId,
      role: "listbox",
      "aria-label": `Suggestions for ${fieldName}`,
    },
    getItemProps: (index: number) => ({
      id: `${listId}-item-${index}`,
      role: "option",
      "aria-selected": index === activeIndex,
      onClick: () => selectSuggestion(suggestions[index].value),
      onMouseEnter: () => setActiveIndex(index),
    }),
    selectSuggestion,
    dismiss,
    fetchSuggestions,
  };
}
