"use client";

import { useRef, forwardRef, useId } from "react";
import { Sparkles, Loader2, ChevronDown } from "lucide-react";
import {
  useSmartFormAutofill,
  UseSmartFormAutofillOptions,
} from "@/hooks/useSmartFormAutofill";
import { useSmartUIConfig } from "@/providers/SmartUIProvider";

interface SmartFormFieldProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "onChange" | "onKeyDown"> {
  label: string;
  fieldName: string;
  fieldType?: UseSmartFormAutofillOptions["fieldType"];
  formContext?: Record<string, string>;
  onValueChange?: (value: string) => void;
  /** Override API endpoint (falls back to SmartUIProvider or /api/suggest) */
  apiEndpoint?: string;
  /** Show AI badge */
  showBadge?: boolean;
  /** Container class */
  containerClassName?: string;
  /** Label class */
  labelClassName?: string;
  /** Input wrapper class */
  inputWrapperClassName?: string;
  /** Dropdown class */
  dropdownClassName?: string;
  /** Suggestion item class */
  itemClassName?: string;
  /** Active suggestion item class */
  activeItemClassName?: string;
}

export const SmartFormField = forwardRef<HTMLInputElement, SmartFormFieldProps>(
  function SmartFormField(
    {
      label,
      fieldName,
      fieldType = "text",
      formContext = {},
      onValueChange,
      apiEndpoint,
      showBadge = true,
      containerClassName = "",
      labelClassName = "",
      inputWrapperClassName = "",
      dropdownClassName = "",
      itemClassName = "",
      activeItemClassName = "",
      value,
      ...inputProps
    },
    forwardedRef
  ) {
    const { apiEndpoint: ctxEndpoint, debounceMs } = useSmartUIConfig();
    const localRef = useRef<HTMLInputElement>(null);
    const ref = (forwardedRef as React.RefObject<HTMLInputElement>) || localRef;
    const labelId = useId();

    const {
      suggestions,
      isOpen,
      loading,
      activeIndex,
      inputProps: autofillInputProps,
      listProps,
      getItemProps,
      selectSuggestion,
    } = useSmartFormAutofill({
      fieldName,
      fieldType,
      formContext,
      apiEndpoint: apiEndpoint || ctxEndpoint || "/api/suggest",
      debounceMs,
      onSelect: (val) => {
        // Update the input value via ref (works with controlled + uncontrolled)
        if (ref.current) {
          const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
            window.HTMLInputElement.prototype,
            "value"
          )?.set;
          nativeInputValueSetter?.call(ref.current, val);
          ref.current.dispatchEvent(new Event("input", { bubbles: true }));
        }
        onValueChange?.(val);
      },
    });

    return (
      <div className={`relative flex flex-col gap-1 ${containerClassName}`}>
        {/* Label */}
        <label
          id={labelId}
          htmlFor={`smart-field-${fieldName}`}
          className={`text-sm font-medium text-slate-700 dark:text-slate-300 ${labelClassName}`}
        >
          {label}
          {showBadge && (
            <span
              aria-label="AI-assisted field"
              className="ml-2 inline-flex items-center gap-1 text-[10px] font-bold
                text-primary bg-primary/10 px-1.5 py-0.5 rounded-full uppercase tracking-widest"
            >
              <Sparkles className="w-2.5 h-2.5" aria-hidden="true" />
              AI
            </span>
          )}
        </label>

        {/* Input wrapper */}
        <div
          className={`relative flex items-center bg-white dark:bg-slate-900
            border border-slate-200 dark:border-slate-700 rounded-xl
            focus-within:border-primary focus-within:ring-2 focus-within:ring-primary/20
            transition-all ${inputWrapperClassName}`}
        >
          <input
            {...inputProps}
            {...autofillInputProps}
            ref={ref}
            id={`smart-field-${fieldName}`}
            value={value}
            aria-labelledby={labelId}
            className={`flex-1 bg-transparent px-4 py-3 text-sm text-slate-800
              dark:text-slate-100 placeholder:text-slate-400 border-none
              focus:outline-none rounded-xl ${inputProps.className || ""}`}
          />

          {/* Right indicator */}
          <div className="pr-3 flex items-center gap-1.5 shrink-0" aria-hidden="true">
            {loading ? (
              <Loader2 className="w-4 h-4 animate-spin text-primary" />
            ) : suggestions.length > 0 ? (
              <ChevronDown
                className={`w-4 h-4 text-slate-400 transition-transform ${
                  isOpen ? "rotate-180" : ""
                }`}
              />
            ) : (
              <Sparkles className="w-4 h-4 text-slate-300" />
            )}
          </div>
        </div>

        {/* Suggestions dropdown */}
        {isOpen && suggestions.length > 0 && (
          <ul
            {...listProps}
            className={`absolute top-full left-0 right-0 mt-1 z-50
              bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700
              rounded-xl shadow-lg overflow-hidden py-1
              max-h-48 overflow-y-auto ${dropdownClassName}`}
          >
            {suggestions.map((s, i) => (
              <li
                key={i}
                {...getItemProps(i)}
                className={`px-4 py-2.5 text-sm cursor-pointer flex items-center justify-between
                  transition-colors
                  ${
                    i === activeIndex
                      ? `bg-primary/10 text-primary font-medium ${activeItemClassName}`
                      : `text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800 ${itemClassName}`
                  }`}
              >
                <span>{s.value}</span>
                {s.confidence >= 0.9 && (
                  <Sparkles
                    className="w-3 h-3 text-amber-400 shrink-0"
                    aria-label="High confidence"
                  />
                )}
              </li>
            ))}
          </ul>
        )}
      </div>
    );
  }
);

SmartFormField.displayName = "SmartFormField";
export default SmartFormField;
